<?php declare(strict_types=1); /** @var Closure(mixed):string $escape */ $editing=$department!==null; ?>
<header class="section-heading"><div><span class="status">ADM · Tickets</span><h1><?= $editing?'Editar setor':'Novo setor' ?></h1><p class="meta">Os usuários selecionados receberão e poderão atender tickets deste setor.</p></div><a class="button-secondary" href="<?= $escape($basePath) ?>/ticket-departments">Cancelar</a></header>
