<section class="card"><div class="card-body"><form method="post" action="<?= $escape($basePath) ?>/ticket-departments<?= $editing?'/'.(int)$department['id']:'' ?>"><?= $csrfField ?><div class="form-field"><label for="department-name">Nome do setor <span class="required">*</span></label><input id="department-name" name="name" required minlength="2" maxlength="120" value="<?= $escape($department['name']??'') ?>"></div><fieldset class="ticket-users"><legend>Usuários do setor</legend><?php foreach($users as$user):?><label><input type="checkbox" name="users[]" value="<?= (int)$user['id'] ?>"<?= in_array((int)$user['id'],$selectedUsers,true)?' checked':'' ?>><span><strong><?= $escape($user['name']) ?></strong><small><?= $escape($user['email']) ?></small></span></label><?php endforeach;?></fieldset><label class="check-row"><input type="checkbox" name="is_active" value="1"<?= !$editing||(int)$department['is_active']===1?' checked':'' ?>> Setor ativo</label><button class="button-primary" type="submit">Salvar setor</button></form></div></section>
